package main

import (
	"fmt"
	"github.com/golang-jwt/jwt/v5"
	"time"
)

func main() {
	// Example token with valid claims
	validToken := "eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.eyJuYW1lIjoiSm9obiBEb24iLCJleHAiOjE2NjM5MjQwMDB9"
	key := "secret-key"

	// Parse and validate the token
	token, err := jwt.Parse(validToken, func(t *jwt.Token) (interface{}, error) {
		if _, ok := t.Method.(*jwt.SigningMethodHMAC); !ok {
			return nil, fmt.Errorf("unexpected signing method")
		}
		return []byte(key), nil
	})

	if err != nil {
		fmt.Println("Error parsing token:", err)
		return
	}

	if !token.Valid {
		fmt.Println("Invalid token")
		return
	}

	claims, ok := token.Claims.(jwt.MapClaims)
	if !ok {
		fmt.Println("Failed to convert claims")
		return
	}

	// Validate specific claims
	if claims["exp"] != nil {
		exp, ok := claims["exp"].(float64)
		if ok {
			if time.Unix(int64(exp), 0).Before(time.Now()) {
				fmt.Println("Token has expired")
				return
			}
		}
	}

	fmt.Println("Valid token with claims:", claims)
}

